import { EditorState, Compartment } from "@codemirror/state";
import {
  EditorView,
  keymap,
  lineNumbers,
  highlightActiveLine,
  drawSelection,
} from "@codemirror/view";
import {
  defaultKeymap,
  history,
  historyKeymap,
  indentWithTab,
} from "@codemirror/commands";
import {
  StreamLanguage,
  syntaxHighlighting,
  defaultHighlightStyle,
  bracketMatching,
} from "@codemirror/language";
import { searchKeymap, highlightSelectionMatches } from "@codemirror/search";

const typstLanguage = StreamLanguage.define<{ comment: boolean }>({
  startState: () => ({ comment: false }),
  token(stream, state) {
    if (state.comment) {
      if (stream.skipTo("*/")) {
        stream.match("*/");
        state.comment = false;
      } else stream.skipToEnd();
      return "comment";
    }
    if (stream.match("//")) {
      stream.skipToEnd();
      return "comment";
    }
    if (stream.match("/*")) {
      state.comment = true;
      return "comment";
    }
    if (stream.match(/"(?:[^"\\]|\\.)*"?/)) return "string";
    if (stream.sol() && stream.match(/=+\s/)) {
      stream.skipToEnd();
      return "heading";
    }
    if (stream.match(/#[a-zA-Z_][\w-]*/)) return "keyword";
    if (
      stream.match(/\b(?:true|false|none|auto|let|set|show|import|include)\b/)
    )
      return "keyword";
    if (stream.match(/\b\d+(?:\.\d+)?(?:pt|em|cm|mm|in|%)?/)) return "number";
    stream.next();
    return null;
  },
});

export function mountTypstCodeEditor(
  element: HTMLElement,
  source: string,
  options: {
    readOnly: boolean;
    onChange(source: string): void;
    onApply(): void;
  },
) {
  const readOnly = new Compartment();
  let settingValue = false;
  const view = new EditorView({
    parent: element,
    state: EditorState.create({
      doc: source,
      extensions: [
        lineNumbers(),
        history(),
        drawSelection(),
        highlightActiveLine(),
        bracketMatching(),
        highlightSelectionMatches(),
        typstLanguage,
        syntaxHighlighting(defaultHighlightStyle),
        EditorView.lineWrapping,
